/* Toolbar zone interactive element normalization.
 * Placed outside @layer so it overrides Tailwind utility classes (border, divide, etc.)
 * which live in @layer utilities and beat @layer base by cascade priority.
 * Uses design tokens (--toolbar-*, --spacing-*, --text-*, --size-*) for all values. */

[data-slot="toolbar-zone"] :is([data-slot="toggle-group"], [data-slot="button-group"]) {
  border-style: none;
  height: 100%;
}

[data-slot="toolbar-zone"] :is([data-slot="toggle-group"], [data-slot="button-group"]) > :not(:first-child) {
  border-inline-start-width: 0;
