[data-slot="toolbar-zone"] :is([data-slot="toggle-group-item"], [data-slot="button-group-item"]) {
  height: 100%;
  line-height: 1;
  padding-block: var(--spacing-single);
  padding-inline: var(--spacing-double);
  gap: var(--spacing-single);
  aspect-ratio: auto;
  font-size: var(--text-sm);
  font-weight: 500;
}

[data-slot="toolbar-zone"] :is([data-slot="toggle-group-item"], [data-slot="button-group-item"]) > span {
  font-size: var(--text-xs);
  line-height: var(--text-xs--line-height);
  white-space: nowrap;
}

[data-slot="toolbar-zone"] :is([data-slot="toggle-group-item"], [data-slot="button-group-item"]) svg {
  width: var(--size-tiny);
  height: var(--size-tiny);
  flex-shrink: 0;
}

[data-slot="toolbar-zone"] [data-slot="action"] {
  border-style: none;
  height: 100%;
  line-height: 1;
  padding-block: var(--spacing-single);
  padding-inline: var(--spacing-double);
  gap: var(--spacing-single);
  aspect-ratio: auto;
  font-size: var(--text-sm);
  font-weight: 500;
}

[data-slot="toolbar-zone"] [data-slot="action"] > span {
  font-size: var(--text-xs);
  line-height: var(--text-xs--line-height);
  white-space: nowrap;
}

[data-slot="toolbar-zone"] [data-slot="action"] svg {
  width: var(--size-tiny);
  height: var(--size-tiny);
  flex-shrink: 0;
}

/* Unify active-state visuals across all toolbar interactive elements. */
[data-slot="toolbar-zone"] [data-slot="toggle-group-item"][data-state="on"] {
  background-color: var(--active-base);
  color: var(--active-foreground);
}

[data-slot="toolbar-zone"] [data-slot="toggle-group-item"][data-state="on"]:hover {
  background-color: color-mix(in oklab, var(--active-base) 90%, black);
  color: var(--active-foreground);
}

