  position: relative;
  transform: translateY(0);
  transition: none;
  z-index: var(--z-navbar);
}

.fullscreen #navbar:hover,
.fullscreen #navbar:focus-within,
.fullscreen #compose\.sketchpad\.navbar:hover,
.fullscreen #compose\.sketchpad\.navbar:focus-within,
.fullscreen [data-slot="navbar"]:hover,
.fullscreen [data-slot="navbar"]:focus-within {
  transform: translateY(0);
}

.fullscreen #footer {
  position: relative;
  transform: translateY(0);
  transition: none;
  z-index: var(--z-footer);
}

.fullscreen #footer:hover,
.fullscreen #footer:focus-within {
  transform: translateY(0);
}

.fullscreen:has(#navbar:hover) #navbar,
.fullscreen:has(#compose\.sketchpad\.navbar:hover) #compose\.sketchpad\.navbar,
.fullscreen:has([data-slot="navbar"]:hover) [data-slot="navbar"],
.fullscreen:has(#footer:hover) #footer {
  transform: translateY(0);
}

@media (pointer: coarse) {
  .fullscreen #navbar,
  .fullscreen #compose\.sketchpad\.navbar,
  .fullscreen [data-slot="navbar"],
  .fullscreen #footer {
    transition: none;
  }
}

